<?php
/** Cost Trends table fragment. Caller supplies $pagination and $filter. */
$ctMoney=static fn($v)=>$v===null?'Not Recorded':money($v/100);
$ctUrl=static fn($page,$size=null)=>'?'.http_build_query(array_merge($filter,['page'=>$page,'size'=>$size??$filter['size']]));
?>
<div id="ct-funding-content"><div class="ct-scroll"><table class="tc-table"><thead><tr><th>Trip / Route</th><th>Estimated Cost</th><th>Approved Funding</th><th>Actual Recorded Cost</th><th>Remaining / Shortfall</th><th>Status</th></tr></thead><tbody>
<?php if(!$pagination['rows']):?><tr><td colspan="6" class="ct-empty-cell">No data available for the selected period.</td></tr><?php endif;?>
<?php foreach($pagination['rows'] as $r):$financial=ct_balance($r);$state=$financial['status'];?><tr><td><?php if($filter['source']==='live'):?><a href="<?=BASE_URL?>/trip-details.php?id=<?=urlencode($r['id'])?>"><?=e($r['id'])?></a><?php else:?><span class="ct-test-trip"><?=e($r['id'])?></span><?php endif;?><small><?=e($r['origin'].' → '.$r['destination'])?></small></td><td><?=$ctMoney($r['estimate'])?></td><td><?=$ctMoney($r['funding'])?></td><td><?=$ctMoney($financial['cost'])?><?php if($financial['cost']!==null&&!ct_complete($r)):?><small>Partial expense recording</small><?php endif;?></td><td class="<?=$financial['balance']===null?'':($financial['balance']<0?'ct-negative':'ct-positive')?>"><?=$financial['balance']===null?'Not Applicable':($financial['balance']<0?'−':'').money(abs($financial['balance'])/100)?></td><td><span class="ct-status <?=in_array($state,['Under Allowance','Within Allowance'],true)?'ct-ok':($state==='Over Allowance'?'ct-over':'ct-pending')?>" title="<?=e($state==='Within Allowance'?'Recorded costs are within the final 5% of approved allowance.':$state)?>"><?=e($state)?></span></td></tr><?php endforeach;?></tbody></table></div>
<div class="ct-pagination"><span>Showing <?=$pagination['start']?>–<?=$pagination['end']?> of <?=$pagination['total']?> trips</span><div><label for="ct-page-size" class="visually-hidden">Records per page</label><select id="ct-page-size"><?php foreach([10,20,50] as $size):?><option value="<?=$size?>" <?=$pagination['size']===$size?'selected':''?>><?=$size?> per page</option><?php endforeach;?></select><nav aria-label="Delivery cost pages"><a href="<?=e($ctUrl(max(1,$pagination['page']-1)))?>" data-ct-page <?=$pagination['page']===1?'aria-disabled="true" tabindex="-1"':''?> aria-label="Previous page">‹</a><?php $pageNumbers=array_unique(array_merge([1,$pagination['pages']],range(max(1,$pagination['page']-2),min($pagination['pages'],$pagination['page']+2))));sort($pageNumbers);$prior=0;foreach($pageNumbers as $p):if($prior&&$p>$prior+1):?><span>…</span><?php endif;?><a href="<?=e($ctUrl($p))?>" data-ct-page <?=$p===$pagination['page']?'aria-current="page"':''?>><?=$p?></a><?php $prior=$p;endforeach;?><a href="<?=e($ctUrl(min($pagination['pages'],$pagination['page']+1)))?>" data-ct-page <?=$pagination['page']===$pagination['pages']?'aria-disabled="true" tabindex="-1"':''?> aria-label="Next page">›</a></nav></div></div><p class="ct-page-message" role="status" aria-live="polite"></p></div>
